   125→const TestimonialsCarousel = ({
   126→  testimonials,
   127→  locale,
   128→}: {
   129→  testimonials: Testimonial[];
   130→  locale: string;
   131→}) => {
   132→  const [currentIndex, setCurrentIndex] = useState(0);
   133→  const [isPaused, setIsPaused] = useState(false);
   134→
   135→  // Duplicate array for infinite loop effect
   136→  const extendedTestimonials = [...testimonials, ...testimonials, ...testimonials];
   137→  const offset = testimonials.length; // Start from middle set
   138→
   139→  const nextSlide = useCallback(() => {
   140→    setCurrentIndex((prev) => (prev + 1) % testimonials.length);
   141→  }, [testimonials.length]);
   142→
   143→  const prevSlide = useCallback(() => {
   144→    setCurrentIndex((prev) => (prev - 1 + testimonials.length) % testimonials.length);
   145→  }, [testimonials.length]);
   146→
   147→  // Auto-scroll lent (6 secondes)
   148→  useEffect(() => {
   149→    if (isPaused) return;
   150→    const interval = setInterval(nextSlide, 6000);
   151→    return () => clearInterval(interval);
   152→  }, [isPaused, nextSlide]);
   153→
   154→  // Calculate the translateX percentage
   155→  // Each card is ~33.33% width on desktop with gap
   156→  const getTranslateX = () => {
   157→    // We show 3 cards at a time, so each step moves by 1 card width (~33.33%)
   158→    return `calc(-${(currentIndex + offset) * 33.333}% - ${(currentIndex + offset) * 8}px)`;
   159→  };
   160→
   161→  return (
   162→    <section
   163→      className="py-24 bg-neo-surface overflow-hidden"
   164→      onMouseEnter={() => setIsPaused(true)}
   165→      onMouseLeave={() => setIsPaused(false)}
   166→    >
   167→      <div className="container mx-auto px-4 md:px-6">
   168→        {/* Header */}
   169→        <div className="flex flex-col md:flex-row md:items-end md:justify-between mb-12">
   170→          <div>
   171→            <div className="font-mono font-bold text-neo-accent mb-4 flex items-center gap-2">
   172→              <span className="bg-neo-text text-neo-text-inverse px-2 py-1">SECT. 02.4</span>
   173→              <span className="text-neo-text/60">
   174→                // {locale === "fr" ? "AVIS CLIENTS" : "CLIENT REVIEWS"}
   175→              </span>
   176→            </div>
   177→            <h2 className="text-4xl md:text-5xl font-black uppercase tracking-tight text-neo-text">
   178→              {locale === "fr" ? "Témoignages" : "Testimonials"}
   179→            </h2>
   180→            <p className="font-mono text-sm text-neo-text/60 mt-2 max-w-md">
   181→              {locale === "fr"
   182→                ? "Retours de mes collaborateurs sur SoundBetter"
   183→                : "Feedback from my collaborators on SoundBetter"}
   184→            </p>
   185→          </div>
   186→
   187→          {/* Navigation Arrows */}
   188→          <div className="flex items-center gap-3 mt-6 md:mt-0">
   189→            <button
   190→              onClick={prevSlide}
   191→              className="w-12 h-12 bg-neo-text text-neo-text-inverse flex items-center justify-center border-2 border-neo-border hover:bg-neo-accent hover:text-neo-text transition-colors"
   192→              aria-label="Previous"
   193→            >
   194→              <ChevronLeft className="w-6 h-6" />
   195→            </button>
   196→            <button
   197→              onClick={nextSlide}
   198→              className="w-12 h-12 bg-neo-text text-neo-text-inverse flex items-center justify-center border-2 border-neo-border hover:bg-neo-accent hover:text-neo-text transition-colors"
   199→              aria-label="Next"
   200→            >
   201→              <ChevronRight className="w-6 h-6" />
   202→            </button>
   203→          </div>
   204→        </div>
   205→
   206→        {/* Carousel - Sliding container */}
   207→        <div className="relative overflow-hidden py-2 -my-2">
   208→          <motion.div
   209→            className="flex gap-6 pt-2"
   210→            animate={{ x: getTranslateX() }}
   211→            transition={{ duration: 0.6, ease: [0.25, 0.4, 0.25, 1] }}
   212→          >
   213→            {extendedTestimonials.map((testimonial, index) => (
   214→              <div
   215→                key={`${testimonial.id}-${index}`}
   216→                className="w-full md:w-[calc(50%-12px)] lg:w-[calc(33.333%-16px)] flex-shrink-0"
   217→              >
   218→                <TestimonialCard testimonial={testimonial} />
   219→              </div>
   220→            ))}
   221→          </motion.div>
   222→        </div>
   223→
   224→        {/* Progress Dots */}
   225→        <div className="flex justify-center gap-3 mt-8">
   226→          {testimonials.map((_, index) => (
   227→            <button
   228→              key={index}
   229→              onClick={() => setCurrentIndex(index)}
   230→              className={`h-3 border-2 border-neo-border transition-all duration-300 ${
   231→                index === currentIndex ? "w-10 bg-neo-accent" : "w-3 bg-neo-bg hover:bg-neo-text/20"
   232→              }`}
   233→              aria-label={`Go to slide ${index + 1}`}
   234→            />
   235→          ))}
   236→        </div>
   237→
   238→        {/* CTA SoundBetter - Orange accent button */}
   239→        <div className="text-center mt-12">
   240→          <a
   241→            href="https://soundbetter.com/profiles/402365-lo%C3%AFc-ghanem--voyager1"
   242→            target="_blank"
   243→            rel="noopener noreferrer"
   244→            className="inline-flex items-center gap-3 bg-neo-accent text-neo-text-inverse px-8 py-4 font-bold uppercase tracking-wide border-2 border-neo-border hover:bg-neo-text hover:text-neo-accent transition-colors shadow-[4px_4px_0px_0px_var(--neo-text)] hover:shadow-none hover:translate-x-1 hover:translate-y-1"
   245→          >
   246→            <Star className="w-5 h-5" />
   247→            {locale === "fr"
   248→              ? "Voir tous les avis sur SoundBetter"
   249→              : "View All Reviews on SoundBetter"}
   250→            <ExternalLink className="w-5 h-5" />
   251→          </a>
