     1→"use client";
     2→
     3→import { ArrowDown } from "lucide-react";
     4→import { motion } from "framer-motion";
     5→import { useTranslations } from "next-intl";
     6→import { useEffect, useState } from "react";
     7→import { usePathname } from "next/navigation";
     8→import { NeoCookieConsent } from "@/components/neo-brutalist/legal/NeoCookieConsent";
     9→import { GlobalAudioPlayerMount } from "@/components/neo-brutalist/player/GlobalAudioPlayerMount";
    10→
    11→export function LayoutContent({ children }: { children: React.ReactNode }) {
    12→  const pathname = usePathname();
    13→  const t = useTranslations("home.splitHero");
    14→  const [scrollIndicatorProgress, setScrollIndicatorProgress] = useState(0);
    15→
    16→  useEffect(() => {
    17→    const handleScroll = () => {
    18→      const progress = Math.min(window.scrollY / 200, 1);
    19→      setScrollIndicatorProgress(progress);
    20→    };
    21→
    22→    handleScroll();
    23→    window.addEventListener("scroll", handleScroll, { passive: true });
    24→    return () => window.removeEventListener("scroll", handleScroll);
    25→  }, []);
    26→
    27→  // Toutes les pages publiques utilisent le design Neo-Brutalist
    28→  // qui gère sa propre navbar et footer dans chaque composant de page
    29→  // Seules les routes admin nécessitent potentiellement un layout différent
    30→  const isAdminRoute = pathname?.includes("/admin");
    31→  const isLoginRoute = pathname?.includes("/login");
    32→  const isLegalPage = pathname?.includes("/privacy-policy") || pathname?.includes("/terms-of-use");
    33→
    34→  if (isAdminRoute || isLoginRoute) {
    35→    // L'admin gère son propre layout
    36→    return <main className="min-h-screen">{children}</main>;
    37→  }
    38→
    39→  // Pages Neo-Brutalist - elles incluent leur propre NeoNavbar et NeoFooter
    40→  return (
    41→    <>
    42→      <main className="min-h-screen">{children}</main>
    43→      <GlobalAudioPlayerMount />
    44→      <motion.div
    45→        initial={{ opacity: 1, y: 0 }}
    46→        animate={{ opacity: 1 - scrollIndicatorProgress }}
    47→        transition={{ duration: 0.6, ease: "easeOut" }}
    48→        className="hidden md:flex fixed right-1 md:right-4 top-1/2 -translate-y-1/2 pr-[env(safe-area-inset-right)] pointer-events-none z-50"
    49→        aria-hidden="true"
    50→      >
    51→        <div className="flex flex-col items-center gap-2">
    52→          <span
    53→            className={`font-mono text-[10px] uppercase tracking-[0.25em] [writing-mode:vertical-rl] ${
    54→              isLegalPage ? "text-white" : "text-neo-text/70"
    55→            }`}
    56→          >
    57→            {t("scrollDown")}
    58→          </span>
    59→          <motion.div
    60→            animate={{ y: [0, 10, 0] }}
    61→            transition={{ repeat: Infinity, duration: 2 }}
    62→            className="drop-shadow-[0_4px_0_rgba(0,0,0,0.25)]"
    63→          >
    64→            <ArrowDown size={24} className={isLegalPage ? "text-white" : "text-neo-accent"} />
    65→          </motion.div>
    66→        </div>
    67→      </motion.div>
    68→      <NeoCookieConsent />
    69→    </>
    70→  );
    71→}
